// nl_rt.h - runtime of the native islands generated by nlift.py (FPS4-ISLANDS).
//
// Each guest AArch64 instruction of a lifted function becomes one call of these inline helpers on C++
// locals (x registers as uint64_t, vector registers as __m128i), so clang allocates the guest registers
// to host registers across the whole function. Semantics follow the AArch64 instruction exactly for the
// cases the islands run (finite inputs; FPCR.FZ mirrored by MXCSR.FTZ|DAZ around the island; RN rounding).
// FP fused multiply-add forms map to FMA3 (one rounding), so FMLA/FMLS are bit-exact.
#pragma once
#include <immintrin.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

namespace nl {

typedef __m128i V;

static inline __m128 F(V v) { return _mm_castsi128_ps(v); }
static inline V I(__m128 v) { return _mm_castps_si128(v); }
static inline V lo64(V v) { return _mm_move_epi64(v); }              // zero bits 64-127
static inline V lo32(V v) { return I(_mm_move_ss(_mm_setzero_ps(), F(v))); }  // keep lane 0 only

// ---- constants / moves ----
static inline V vconst(uint64_t lo, uint64_t hi) { return _mm_set_epi64x((long long)hi, (long long)lo); }
static inline V vzero() { return _mm_setzero_si128(); }
static inline V dup4(V n, int j) {
    switch (j) {
    case 0: return _mm_shuffle_epi32(n, 0x00);
    case 1: return _mm_shuffle_epi32(n, 0x55);
    case 2: return _mm_shuffle_epi32(n, 0xAA);
    default: return _mm_shuffle_epi32(n, 0xFF);
    }
}
static inline V dup2(V n, int j) { return lo64(dup4(n, j)); }
static inline V dupw4(uint32_t w) { return _mm_set1_epi32((int)w); }
static inline uint32_t lane32(V n, int j) {
    switch (j) {
    case 0: return (uint32_t)_mm_cvtsi128_si32(n);
    case 1: return (uint32_t)_mm_extract_epi32(n, 1);
    case 2: return (uint32_t)_mm_extract_epi32(n, 2);
    default: return (uint32_t)_mm_extract_epi32(n, 3);
    }
}
static inline uint64_t lane64(V n, int j) { return j ? (uint64_t)_mm_extract_epi64(n, 1) : (uint64_t)_mm_cvtsi128_si64(n); }
static inline V ins32(V d, int i, uint32_t w) {
    switch (i) {
    case 0: return _mm_insert_epi32(d, (int)w, 0);
    case 1: return _mm_insert_epi32(d, (int)w, 1);
    case 2: return _mm_insert_epi32(d, (int)w, 2);
    default: return _mm_insert_epi32(d, (int)w, 3);
    }
}
static inline V ins64(V d, int i, uint64_t w) { return i ? _mm_insert_epi64(d, (long long)w, 1) : _mm_insert_epi64(d, (long long)w, 0); }
static inline V ins_s(V d, int i, V n, int j) { return ins32(d, i, lane32(n, j)); }
static inline V ins_d(V d, int i, V n, int j) { return ins64(d, i, lane64(n, j)); }
static inline V scal_s(V n, int j) { return _mm_cvtsi32_si128((int)lane32(n, j)); }  // mov sD, vN.s[j]
static inline V fromw(uint32_t w) { return _mm_cvtsi32_si128((int)w); }               // fmov sD, wN

// ---- logic ----
static inline V vand(V a, V b) { return _mm_and_si128(a, b); }
static inline V vorr(V a, V b) { return _mm_or_si128(a, b); }
static inline V veor(V a, V b) { return _mm_xor_si128(a, b); }
static inline V vbic(V a, V b) { return _mm_andnot_si128(b, a); }
static inline V vmvn(V a) { return _mm_xor_si128(a, _mm_set1_epi32(-1)); }
static inline V vbsl(V d, V n, V m) { return _mm_or_si128(_mm_and_si128(d, n), _mm_andnot_si128(d, m)); }

// ---- permutes ----
static inline V tbl1_16(V t, V idx) {  // result bytes for the 16 index bytes
    const V ok = _mm_cmpeq_epi8(_mm_and_si128(idx, _mm_set1_epi8((char)0xF0)), _mm_setzero_si128());
    return _mm_and_si128(_mm_shuffle_epi8(t, idx), ok);
}
static inline V tbl2_16(V t0, V t1, V idx) {
    const V hi = _mm_and_si128(idx, _mm_set1_epi8((char)0xF0));
    const V in0 = _mm_cmpeq_epi8(hi, _mm_setzero_si128());
    const V in1 = _mm_cmpeq_epi8(hi, _mm_set1_epi8(0x10));
    const V lo = _mm_and_si128(idx, _mm_set1_epi8(0x0F));
    return _mm_or_si128(_mm_and_si128(_mm_shuffle_epi8(t0, lo), in0), _mm_and_si128(_mm_shuffle_epi8(t1, lo), in1));
}
static inline V tbl1_8(V t, V idx) { return lo64(tbl1_16(t, idx)); }
static inline V tbl2_8(V t0, V t1, V idx) { return lo64(tbl2_16(t0, t1, idx)); }
template <int N> static inline V ext16(V n, V m) { return _mm_alignr_epi8(m, n, N); }
template <int N> static inline V ext8(V n, V m) { return lo64(_mm_srli_si128(_mm_unpacklo_epi64(n, m), N)); }
static inline V zip1_2s(V n, V m) { return lo64(_mm_unpacklo_epi32(n, m)); }
static inline V zip1_4s(V n, V m) { return _mm_unpacklo_epi32(n, m); }
static inline V zip2_2s(V n, V m) { return lo64(_mm_unpacklo_epi32(_mm_srli_si128(n, 4), _mm_srli_si128(m, 4))); }
static inline V zip2_4s(V n, V m) { return _mm_unpackhi_epi32(n, m); }

// ---- AArch64 NaN semantics ----
// x86 and AArch64 give the same result for every operation whose result is not a NaN. When a lane's result is a
// NaN, the slow path redoes the lanes with the AArch64 rules: an input NaN is propagated by operand priority
// (signalling first, then quiet, in AArch64 operand order; quietened), otherwise the default NaN 0x7FC00000
// (x86 would give 0xFFC00000). FPCR.DN is not supported by the islands (the hooks refuse such an FPCR).
static inline bool isnan32(uint32_t x) { return (x & 0x7fffffffu) > 0x7f800000u; }
static inline bool issnan32(uint32_t x) { return isnan32(x) && !(x & 0x00400000u); }
static inline uint32_t f2u(float f) { uint32_t u; memcpy(&u, &f, 4); return u; }
static inline float u2f(uint32_t u) { float f; memcpy(&f, &u, 4); return f; }
static inline bool nan2(uint32_t a, uint32_t b, uint32_t& r) {
    if (issnan32(a)) { r = a | 0x00400000u; return true; }
    if (issnan32(b)) { r = b | 0x00400000u; return true; }
    if (isnan32(a)) { r = a; return true; }
    if (isnan32(b)) { r = b; return true; }
    return false;
}
enum { OP_ADD, OP_SUB, OP_MUL, OP_DIV, OP_FMA, OP_FMS, OP_RSQRTS, OP_SQRT };
static __attribute__((noinline)) V slow_lanes(int op, V va, V vb, V vc) {
    alignas(16) uint32_t a[4], b[4], c[4], r[4];
    _mm_store_si128((V*)a, va);
    _mm_store_si128((V*)b, vb);
    _mm_store_si128((V*)c, vc);
    for (int i = 0; i < 4; ++i) {
        uint32_t x = a[i], y = b[i], z = c[i], o = 0;
        switch (op) {
        case OP_ADD: case OP_SUB: case OP_MUL: case OP_DIV:
            if (!nan2(x, y, o)) {
                const float fx = u2f(x), fy = u2f(y);
                o = f2u(op == OP_ADD ? fx + fy : op == OP_SUB ? fx - fy : op == OP_MUL ? fx * fy : fx / fy);
                if (isnan32(o)) o = 0x7fc00000u;
            }
            break;
        case OP_SQRT:
            if (isnan32(x)) o = x | 0x00400000u;
            else { o = f2u(sqrtf(u2f(x))); if (isnan32(o)) o = 0x7fc00000u; }
            break;
        case OP_FMA: case OP_FMS: {  // x = addend, y = op1 (negated for FMLS), z = op2
            if (op == OP_FMS) y ^= 0x80000000u;
            const float f1 = u2f(y), f2 = u2f(z);
            const bool inf1 = (y & 0x7fffffffu) == 0x7f800000u, inf2 = (z & 0x7fffffffu) == 0x7f800000u;
            const bool zero1 = !isnan32(y) && f1 == 0.0f, zero2 = !isnan32(z) && f2 == 0.0f;
            if (isnan32(x) && !issnan32(x) && ((inf1 && zero2) || (zero1 && inf2))) { o = 0x7fc00000u; break; }
            if (issnan32(x)) o = x | 0x00400000u;
            else if (issnan32(y)) o = y | 0x00400000u;
            else if (issnan32(z)) o = z | 0x00400000u;
            else if (isnan32(x)) o = x;
            else if (isnan32(y)) o = y;
            else if (isnan32(z)) o = z;
            else { o = f2u(fmaf(f1, f2, u2f(x))); if (isnan32(o)) o = 0x7fc00000u; }
            break;
        }
        case OP_RSQRTS: {  // (3 - x*y) / 2, op1 negated
            const uint32_t nx = x ^ 0x80000000u;
            if (!nan2(nx, y, o)) {
                const bool inf1 = (x & 0x7fffffffu) == 0x7f800000u, inf2 = (y & 0x7fffffffu) == 0x7f800000u;
                const bool zero1 = u2f(x) == 0.0f, zero2 = u2f(y) == 0.0f;
                if ((inf1 && zero2) || (zero1 && inf2)) o = f2u(1.5f);
                else o = f2u(fmaf(u2f(nx), u2f(y), 3.0f) * 0.5f);
            }
            break;
        }
        }
        r[i] = o;
    }
    return _mm_load_si128((const V*)r);
}
static inline bool anynan(__m128 r) { return _mm_movemask_ps(_mm_cmpunord_ps(r, r)) != 0; }

// ---- FP vector (4s) ----
static inline V fadd4(V a, V b) { const __m128 r = _mm_add_ps(F(a), F(b)); return anynan(r) ? slow_lanes(OP_ADD, a, b, a) : I(r); }
static inline V fsub4(V a, V b) { const __m128 r = _mm_sub_ps(F(a), F(b)); return anynan(r) ? slow_lanes(OP_SUB, a, b, a) : I(r); }
static inline V fmul4(V a, V b) { const __m128 r = _mm_mul_ps(F(a), F(b)); return anynan(r) ? slow_lanes(OP_MUL, a, b, a) : I(r); }
static inline V fdiv4(V a, V b) { const __m128 r = _mm_div_ps(F(a), F(b)); return anynan(r) ? slow_lanes(OP_DIV, a, b, a) : I(r); }
static inline V fsqrt4(V a) { const __m128 r = _mm_sqrt_ps(F(a)); return anynan(r) ? slow_lanes(OP_SQRT, a, a, a) : I(r); }
static inline V fmla4(V d, V n, V m) { const __m128 r = _mm_fmadd_ps(F(n), F(m), F(d)); return anynan(r) ? slow_lanes(OP_FMA, d, n, m) : I(r); }
static inline V fmls4(V d, V n, V m) { const __m128 r = _mm_fnmadd_ps(F(n), F(m), F(d)); return anynan(r) ? slow_lanes(OP_FMS, d, n, m) : I(r); }
static inline V fabs4(V a) { return _mm_and_si128(a, _mm_set1_epi32(0x7fffffff)); }
static inline V fneg4(V a) { return _mm_xor_si128(a, _mm_set1_epi32((int)0x80000000u)); }
static inline V fcmgt4(V a, V b) { return I(_mm_cmpgt_ps(F(a), F(b))); }
static inline V fcmge4(V a, V b) { return I(_mm_cmpge_ps(F(a), F(b))); }
static inline V fcmeq4(V a, V b) { return I(_mm_cmpeq_ps(F(a), F(b))); }
static inline V faddp2(V a, V b) {  // 2s: {a0+a1, b0+b1}
    const __m128 x = _mm_shuffle_ps(F(a), F(b), _MM_SHUFFLE(1, 0, 1, 0));  // a0 a1 b0 b1
    const __m128 lo = _mm_shuffle_ps(x, x, _MM_SHUFFLE(3, 1, 3, 1)); // a1 b1 a1 b1
    const __m128 ev = _mm_shuffle_ps(x, x, _MM_SHUFFLE(2, 0, 2, 0)); // a0 b0 a0 b0
    return lo64(fadd4(I(ev), I(lo)));
}
static inline V faddp4(V a, V b) {  // 4s: {a0+a1, a2+a3, b0+b1, b2+b3}
    const __m128 ev = _mm_shuffle_ps(F(a), F(b), _MM_SHUFFLE(2, 0, 2, 0));
    const __m128 od = _mm_shuffle_ps(F(a), F(b), _MM_SHUFFLE(3, 1, 3, 1));
    return fadd4(I(ev), I(od));
}
static inline V scvtf4(V a) { return I(_mm_cvtepi32_ps(a)); }
static inline V fcvtzs4(V a) {  // round toward zero, saturating, NaN -> 0 (AArch64 FCVTZS)
    const __m128 f = F(a);
    V r = _mm_cvttps_epi32(f);
    const V big = I(_mm_cmpge_ps(f, _mm_set1_ps(2147483648.0f)));       // -> INT_MAX
    const V nan = I(_mm_cmpunord_ps(f, f));                              // -> 0
    r = _mm_blendv_epi8(r, _mm_set1_epi32(0x7fffffff), big);
    return _mm_andnot_si128(nan, r);
}
// FRSQRTS: (3 - n*m) / 2 with one rounding; inf*0 -> 1.5; NaNs by AArch64 rules (slow path).
static inline V frsqrts4(V n, V m) {
    const __m128 a = F(n), b = F(m);
    if (anynan(_mm_or_ps(_mm_cmpunord_ps(a, a), _mm_cmpunord_ps(b, b)))) return slow_lanes(OP_RSQRTS, n, m, n);
    __m128 r = _mm_mul_ps(_mm_fnmadd_ps(a, b, _mm_set1_ps(3.0f)), _mm_set1_ps(0.5f));
    const __m128 ainf = _mm_cmpeq_ps(_mm_and_ps(a, _mm_castsi128_ps(_mm_set1_epi32(0x7fffffff))), _mm_set1_ps(INFINITY));
    const __m128 binf = _mm_cmpeq_ps(_mm_and_ps(b, _mm_castsi128_ps(_mm_set1_epi32(0x7fffffff))), _mm_set1_ps(INFINITY));
    const __m128 az = _mm_cmpeq_ps(a, _mm_setzero_ps()), bz = _mm_cmpeq_ps(b, _mm_setzero_ps());
    const __m128 sp = _mm_or_ps(_mm_and_ps(ainf, bz), _mm_and_ps(binf, az));
    return I(_mm_blendv_ps(r, _mm_set1_ps(1.5f), sp));
}
// FRSQRTE, single precision, per lane: port of the recompiler's recomp_fp_estimate (rsqrt, width 32), which
// follows the AArch64 pseudocode (8-bit estimate). FPSR side effects are not modelled (islands ignore FPSR).
static inline uint32_t frsqrte_lane(uint32_t bits, uint32_t fpcr) {
    const uint32_t sign = bits & 0x80000000u, expmask = 0x7f800000u, quiet = 0x00400000u;
    uint32_t frac = bits & 0x007fffffu;
    const unsigned rawexp = (bits & expmask) >> 23;
    if (rawexp == 255 && frac) return (fpcr & (1u << 25)) ? (expmask | quiet) : (bits | quiet);
    if (!rawexp && frac && (fpcr & (1u << 24))) frac = 0;
    if (!rawexp && !frac) return sign | expmask;
    if (sign) return expmask | quiet;
    if (rawexp == 255) return 0;
    int exponent = rawexp ? (int)rawexp - 127 : -126;
    uint64_t mant = rawexp ? (0x00800000u | frac) : frac;
    while (mant < 0x00800000u) { mant <<= 1; exponent--; }
    uint64_t a = mant >> (23 - ((exponent % 2 == 0) ? 7 : 8));
    a = a < 256 ? 2 * a + 1 : 2 * (a | 1);
    unsigned lo = 512, hi = 1024;
    while (lo + 1 < hi) { const unsigned mid = (lo + hi) / 2; if (a * mid * mid < (UINT64_C(1) << 28)) lo = mid; else hi = mid; }
    const uint64_t estimate = ((lo + 1) / 2) & 255;
    const int neg = -exponent - 1;
    const int out_exp = neg >= 0 ? neg / 2 : -((-neg + 1) / 2);
    return (uint32_t)(((uint64_t)(out_exp + 127) << 23) | (estimate << 15));
}
static inline V frsqrte4(V a, uint32_t fpcr) {
    alignas(16) uint32_t l[4];
    _mm_store_si128((V*)l, a);
    for (int i = 0; i < 4; ++i) l[i] = frsqrte_lane(l[i], fpcr);
    return _mm_load_si128((const V*)l);
}
// 2s forms: compute 4 lanes, zero the upper half (a 64-bit destination clears bits 64-127).
static inline V fadd2(V a, V b) { return lo64(fadd4(a, b)); }
static inline V fsub2(V a, V b) { return lo64(fsub4(a, b)); }
static inline V fmul2(V a, V b) { return lo64(fmul4(a, b)); }
static inline V fmla2(V d, V n, V m) { return lo64(fmla4(d, n, m)); }
static inline V fmls2(V d, V n, V m) { return lo64(fmls4(d, n, m)); }
// ---- FP scalar (s): lane 0, other lanes cleared ----
static inline V fadds(V a, V b) { return lo32(fadd4(a, b)); }
static inline V fsubs(V a, V b) { return lo32(fsub4(a, b)); }
static inline V fmuls(V a, V b) { return lo32(fmul4(a, b)); }
static inline V fdivs(V a, V b) { return lo32(fdiv4(a, b)); }
static inline V fsqrts(V a) { return lo32(fsqrt4(a)); }
static inline V fsqrts_arm(V a) { return fsqrts(a); }
static inline V fabss(V a) { return lo32(fabs4(a)); }
static inline V fnegs(V a) { return lo32(fneg4(a)); }
static inline V fmadds(V n, V m, V a) { return lo32(fmla4(a, n, m)); }
static inline V fmsubs(V n, V m, V a) { return lo32(fmls4(a, n, m)); }

// ---- scalar FP compare -> NZCV (FCMP) ----
static inline void fcmp_s(V a, V b, int& N, int& Z, int& C, int& Vf) {
    float x, y;
    const uint32_t ax = lane32(a, 0), by = lane32(b, 0);
    memcpy(&x, &ax, 4);
    memcpy(&y, &by, 4);
    if (x != x || y != y) { N = 0; Z = 0; C = 1; Vf = 1; }
    else if (x == y) { N = 0; Z = 1; C = 1; Vf = 0; }
    else if (x < y) { N = 1; Z = 0; C = 0; Vf = 0; }
    else { N = 0; Z = 0; C = 1; Vf = 0; }
}

} // namespace nl
